#!/usr/bin/env bash
set -euo pipefail

verbose=0
output="-"

usage() { echo "usage: $0 [-v] [-o FILE] INPUT" >&2; exit 2; }

while getopts ":vo:h" opt; do
  case $opt in
    v) verbose=1 ;;
    o) output=$OPTARG ;;
    h) usage ;;
    :) echo "option -$OPTARG needs a value" >&2; usage ;;
    \?) echo "unknown option -$OPTARG" >&2; usage ;;
  esac
done
shift $((OPTIND - 1))

[[ $# -ge 1 ]] || usage
(( verbose )) && echo "verbose on, writing to $output, input: $1"

