import bcrypt

# Storing a new password — bcrypt generates and embeds a per-password salt
def hash_password(plaintext: str) -> bytes:
    return bcrypt.hashpw(plaintext.encode(), bcrypt.gensalt(rounds=12))

# Verifying at login — constant-time comparison, no manual salt handling
def verify(plaintext: str, stored_hash: bytes) -> bool:
    return bcrypt.checkpw(plaintext.encode(), stored_hash)

