BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;   -- both updates become permanent together

-- if anything looked wrong before COMMIT:
-- ROLLBACK;  -- discards BOTH updates as if they never happened

-- Consistency in action: the constraint, not your code, enforces the rule.
CREATE TABLE accounts (
  id      serial PRIMARY KEY,
  owner   text NOT NULL,
  balance integer NOT NULL CHECK (balance >= 0)
);

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;  -- balance would go negative
COMMIT;   -- rejected: the CHECK constraint fails, transaction rolls back atomically

-- Session A                         -- Session B
BEGIN;
SELECT balance FROM accounts          
  WHERE id = 1;  -- reads 500          
                                       UPDATE accounts
                                         SET balance = 900 WHERE id = 1;
                                       COMMIT;
-- Under READ COMMITTED a re-read now sees 900;
-- under REPEATABLE READ it still sees the original 500.

-- pin a consistent snapshot for an entire multi-statement report
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM orders WHERE status = 'paid';
-- ... other sessions commit new paid orders here ...
SELECT count(*) FROM orders WHERE status = 'paid';  -- SAME count as the first
COMMIT;

-- strongest correctness; be ready to retry on a serialization failure
BEGIN ISOLATION LEVEL SERIALIZABLE;
-- ...
COMMIT;

-- WRONG: read then write leaves a race window between the two statements
-- BEGIN; SELECT balance ...; (app computes new value); UPDATE balance = :new; COMMIT;

-- RIGHT (atomic): let the database do the arithmetic
UPDATE accounts SET balance = balance - 100 WHERE id = 1;

-- RIGHT (when you must read-decide-write): lock the row first
BEGIN;
SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;  -- others now wait
-- ... application logic decides the new balance ...
UPDATE accounts SET balance = 400 WHERE id = 1;
COMMIT;  -- releases the lock

BEGIN;
INSERT INTO accounts (owner, balance) VALUES ('Maya', 500);

SAVEPOINT before_risky;
INSERT INTO accounts (owner, balance) VALUES ('Leo', -50);  -- violates CHECK, errors
ROLLBACK TO SAVEPOINT before_risky;   -- undo only the bad INSERT

INSERT INTO accounts (owner, balance) VALUES ('Leo', 50);   -- corrected, succeeds
COMMIT;   -- Maya (500) and Leo (50) are both saved

-- Prevent the cycle: always lock lower id first, in BOTH transactions.
BEGIN;
SELECT * FROM accounts WHERE id IN (1, 2) ORDER BY id FOR UPDATE;
-- both rows locked in a deterministic order, so no two transactions can deadlock
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

CREATE TABLE accounts (
  id serial PRIMARY KEY,
  owner text NOT NULL,
  balance integer NOT NULL CHECK (balance >= 0)
);
INSERT INTO accounts (owner, balance) VALUES ('Maya', 500), ('Leo', 500);

-- try it: roll back a transfer and confirm nothing changed
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE owner = 'Maya';
UPDATE accounts SET balance = balance + 100 WHERE owner = 'Leo';
ROLLBACK;
SELECT owner, balance FROM accounts;   -- still 500 and 500

