def read_config(path):
    try:
        with open(path, encoding="utf-8") as f:
            return f.read()
    except FileNotFoundError:
        print(f"no config at {path}; using defaults")
        return ""
    except PermissionError as err:
        print(f"cannot read {path}: {err}")
        return ""

print(read_config("missing.cfg"))

def parse_int(text):
    try:
        value = int(text)
    except ValueError:
        print(f"{text!r} is not a whole number")
        return None
    else:
        print("parsed cleanly")
        return value
    finally:
        print("done attempting parse")

parse_int("42")
parse_int("oops")

class ConfigError(Exception):
    """Raised when configuration is invalid."""

def set_port(value):
    if not (0 < value < 65536):
        raise ConfigError(f"port {value} is out of range")
    return value

try:
    set_port(99999)
except ConfigError as err:
